def get_jd_corpus():
    """Return the full JD corpus list."""
    return JD_CORPUS


def get_jd_texts():
    """Return a list of concatenated title + skills + description strings for embedding."""
    return [
        f"{jd['title']} {' '.join(jd['skills'])} {jd['description']}"
        for jd in JD_CORPUS
    ]
